// WebP variants of the images in public/, generated by scripts/optimize-images.py.
// Importing them through Vite gives hashed file names, which the host serves
// with long-lived immutable caching; plain public/ files get no Cache-Control.
const files = import.meta.glob("/src/assets/img/*.webp", {
  eager: true,
  query: "?url",
  import: "default",
});

const variants = {};
for (const [path, url] of Object.entries(files)) {
  const [, stem, width] = path.match(/\/([^/]+)-(\d+)\.webp$/);
  (variants[stem] ??= []).push({ url, width: Number(width) });
}

// Small images have no meaningful 100vw fallback: without a `sizes` prop the
// browser would otherwise pick the widest logo for a 36px tall header.
const DEFAULT_SIZES = { "zyllo-logo": "180px", "zyllo-icon": "64px" };

/** Returns { src, srcSet, sizes } for a public image like "/hero-home1.png", or null. */
export function getOptimizedImage(publicPath) {
  const stem = typeof publicPath === "string" && publicPath.match(/^\/([^/]+)\.(png|jpe?g)$/)?.[1];
  const list = stem && variants[stem];
  if (!list) return null;
  const sorted = [...list].sort((a, b) => a.width - b.width);
  return {
    src: sorted[sorted.length - 1].url,
    srcSet: sorted.length > 1 ? sorted.map((v) => `${v.url} ${v.width}w`).join(", ") : undefined,
    sizes: DEFAULT_SIZES[stem],
  };
}
